// The brands' own logos, for the bundle concept's mockups only (dev only,
// safe to delete, never imported by lib/main.dart). PUBG Mobile and Libyana
// from Wikimedia Commons, Almadar from almadar.ly, LTT from ltt.ly. Generated
// from PNGs; the app itself shows the logos its catalog serves.

import 'dart:convert';
import 'dart:typed_data';

/// The logo of [brand] (pubg, libyana, almadar, ltt), or null without one.
Uint8List? bundleLogo(String brand) {
  final data = _logos[brand];
  return data == null ? null : base64Decode(data);
}

